import{_ as l,o,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const R=JSON.parse('{"title":"2018-07-12 Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-07-12 Ceph Performance Weekly","date":"2018-07-12T00:00:00.000Z","updated":"2018-07-19T00:00:00.000Z","tags":["Ceph","分布式存储","RocksDB","LRU缓存","内存优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-07-12_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-07-12_Ceph_Performance_Weekly.md","lastUpdated":1780460162000}'),r={name:"posts/2018/2018-07-12_Ceph_Performance_Weekly.md"};function s(n,e,a,p,g,c){return o(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Josh、Sage、Braddock、Alec、Murph、Kevin、Howard、Peng等（部分人员未出席）</p><p><strong>会议主题</strong>： Ceph分布式存储项目开发讨论</p><p><strong>会议内容</strong>：</p><ul><li><strong>参会人数</strong>： 由于Josh和Sage未能参加会议，参会人数较少。</li><li><strong>议程</strong>： <ul><li>Aaron 85提交的关于数据编码条带缓存的新PR。</li><li>Bend LRU缓存相关PR的更新。</li><li>Peng正在研究的K be finalized线程的延迟问题。</li><li>两个新的PR： <ol><li>将RocksDB的LRU缓存集成到Ceph中，并修改了高优先级池的使用方式。</li><li>分析OSD使用的堆内存和未映射内存，用于动态调整Blue Store缓存的大小。</li></ol></li></ul></li><li><strong>讨论重点</strong>： <ul><li><strong>Bend LRU缓存</strong>： 该缓存功能表现良好，需要进一步验证并合并。</li><li><strong>RocksDB LRU缓存集成</strong>： 该PR将RocksDB的LRU缓存集成到Ceph中，并修改了高优先级池的使用方式，以优化缓存性能。该PR可能需要一些修改才能回滚到Luminous版本。</li><li><strong>内存使用优化</strong>： 通过分析OSD使用的堆内存和未映射内存，可以动态调整Blue Store缓存的大小，以优化OSD的RSS内存使用。该功能有助于在内存受限的情况下更好地管理OSD的内存使用。</li></ul></li><li><strong>行动计划</strong>： <ul><li>合并Bend LRU缓存相关PR。</li><li>评估RocksDB LRU缓存集成PR，并根据需要做出修改。</li><li>测试并验证内存使用优化功能。</li><li>讨论并解决回滚到Luminous版本时可能遇到的问题。</li></ul></li></ul><p><strong>其他事项</strong>：</p><ul><li>会议中提到了一些计算机科学/ceph相关领域英文关键词，例如： <ul><li>PR (Pull Request)</li><li>LRU (Least Recently Used)</li><li>RocksDB</li><li>Ceph</li><li>OSD (Object Storage Daemon)</li><li>Blue Store</li><li>RSS (Resident Set Size)</li><li>Backport (回滚到旧版本)</li></ul></li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了Ceph分布式存储项目的多个开发议题，并制定了后续的行动计划。会议内容涵盖了缓存优化、内存使用优化等方面，有助于提升Ceph的性能和可靠性。</p><p><strong>改进点</strong>：</p><ol><li>在总结中明确了Josh和Sage未出席的情况。</li><li>对Bend LRU缓存、RocksDB LRU缓存集成和内存使用优化进行了更详细的描述。</li><li>在“其他事项”中增加了会议中提到的关键词，便于读者查阅和理解。</li><li>总结部分强调了会议的成果和未来的行动计划。</li></ol>',12)])])}const u=l(r,[["render",s]]);export{R as __pageData,u as default};
